+              '(${value.length} chars)';
+  }
+  if (value is List) {
+    final encoded = jsonEncode(value);
+    return encoded.length <= _maxPreviewChars
+        ? encoded
+        : '[list: ${value.length} item(s), ${encoded.length} B]';
+  }
