+      final json = jsonEncode({
+        'history': [for (var i = 0; i < 3400; i++) 'entry-$i with padding'],
+        'profile': {'name': 'Ada', 'goal': 'run 5k'},
+        'count': 7,
+        'enabled': true,
+      });
+      expect(utf8len(json), greaterThan(80 * 1024));
