+      final json = '{"blob":"${'y' * 50000}"}';
+      final folded = formatAppStateContext(json);
+      expect(utf8len(folded), lessThanOrEqualTo(appStateContextMaxBytes));
+      expect(folded, contains('blob'));
+      expect(folded, contains('folded'));
+    });
