+      expect(folded, contains('enabled'));
+      // Small scalar values survive as previews.
+      expect(folded, contains('7'));
+      expect(folded, contains('Ada'));
+      // The fold is ANNOUNCED, never silent.
+      expect(folded, contains('folded'));
