    debugPrint(
      '[Fa] finalizeAssistant: stopReason=${message.stopReason}, '
      'contentBlocks=${message.content.length}, '
      'errorMessage=${message.errorMessage}',
    );
    var text = message.content
        .whereType<TextContent>()
        .map((b) => b.text)
        .join();
