+                model: model.id,
+                usage: Usage.zero,
+                stopReason: StopReason.stop,
+                timestamp: DateTime.now(),
+              ),
+            ),
+          );
+          stream.end();
+          return stream;
+        };
+      }
+
+      final env = MemoryExecutionEnv();
+      final manager = FlutterSessionManager(
+        env: env,
+        sessionsRoot: '/sessions',
+      );
+      final service = AgentService(
+        agent: Agent(
+          model: Model(
+            id: 'test-model',
