import 'dart:convert';

const int appStateContextMaxBytes = 8 * 1024;
const int _maxPreviewChars = 60;

String formatAppStateContext(String stateJson, {int budget = appStateContextMaxBytes}) {
  final bytes = utf8.encode(stateJson).length;
  if (bytes <= budget) return stateJson;
  Object? decoded;
  try { decoded = jsonDecode(stateJson); } on FormatException { decoded = null; }
  if (decoded is! Map) {
    if (decoded == null) return _truncate(stateJson, budget, invalid: true);
    return _truncate(stateJson, budget);
  }
  final entries = decoded.entries.toList();
  final buffer = StringBuffer();
  String noteFor(int skipped) =>
      '(app state folded: full JSON is $bytes bytes over the '
      '$budget-byte budget — top-level keys shown'
      '${skipped > 0 ? ', $skipped key(s) omitted for the budget' : ''}; '
      'ask the user or read the app storage for full values)';
  var skipped = 0;
  for (var i = 0; i < entries.length; i++) {
    final line = '  ${entries[i].key}: ${_describe(entries[i].value)}';
    if (utf8.encode('$buffer$line\n${noteFor(0)}').length > budget) {
      skipped = entries.length - i;
      break;
    }
    buffer.writeln(line);
  }
  buffer.write(noteFor(skipped));
  return buffer.toString();
}

String _describe(Object? value) {
  if (value == null) return 'null';
  if (value is bool) return value.toString();
  if (value is num) return value.toString();
  if (value is String) {
    return value.length <= _maxPreviewChars
        ? '"${value.replaceAll('\n', ' ')}"'
        : '"${value.substring(0, _maxPreviewChars)}…" (${value.length} chars)';
  }
  if (value is List) {
    final encoded = jsonEncode(value);
    return encoded.length <= _maxPreviewChars ? encoded : '[list: ${value.length} item(s), ${encoded.length} B]';
  }
  if (value is Map) {
    final encoded = jsonEncode(value);
    return encoded.length <= _maxPreviewChars ? encoded : '{object: ${value.length} key(s), ${encoded.length} B}';
  }
  return value.runtimeType.toString();
}

String _truncate(String text, int budget, {bool invalid = false}) {
  final kind = invalid ? 'unparseable' : 'non-object';
  final note = '\n(app state truncated: $kind JSON exceeded the $budget-byte budget)';
  final room = budget - note.length - 1;
  var cut = text.length;
  while (utf8.encode(text.substring(0, cut)).length > room && cut > 0) {
    cut = (cut * 0.9).floor();
  }
  return '${text.substring(0, cut)}$note';
}

int u8(String s) => utf8.encode(s).length;

void main() {
  // Craft: a big first key to blow the budget, then MANY tiny keys so the
  // break happens on a short line while the omission note grows.
  final map = <String, Object?>{'big': 'x' * 8100};
  for (var i = 0; i < 30; i++) map['k$i'] = i;
  final json = jsonEncode(map);
  final folded = formatAppStateContext(json);
  print('input bytes: ${u8(json)}, folded bytes: ${u8(folded)}, budget: $appStateContextMaxBytes, over: ${u8(folded) - appStateContextMaxBytes}');

  // Case 2: many medium keys, break on a short trailing line
  final map2 = <String, Object?>{};
  for (var i = 0; i < 500; i++) map2['key$i'] = 'v' * 20;
  final json2 = jsonEncode(map2);
  final folded2 = formatAppStateContext(json2);
  print('case2: input ${u8(json2)}, folded ${u8(folded2)}, over: ${u8(folded2) - appStateContextMaxBytes}');

  // Case 3: truncate loop — text with multibyte chars
  final mb = '{"a":"${'ж' * 5000}"';
  final t = formatAppStateContext(mb);
  print('case3 folded bytes: ${u8(t)} (invalid path, budget $appStateContextMaxBytes)');
}
