import 'dart:convert';
const int _maxPreviewChars = 60;
String formatAppStateContext(String stateJson, {int budget = 8192}) {
  final bytes = utf8.encode(stateJson).length;
  if (bytes <= budget) return stateJson;
  Object? decoded;
  try { decoded = jsonDecode(stateJson); } on FormatException { decoded = null; }
  if (decoded is! Map) return 'truncated';
  final entries = decoded.entries.toList();
  final buffer = StringBuffer();
  String noteFor(int skipped) {
    final shown = entries.length - skipped;
    final keysClause = shown == 0
        ? 'no top-level key fits the remaining budget'
        : 'top-level keys shown${skipped > 0 ? ' ($shown of ${entries.length})' : ''}';
    return '(app state folded: full JSON is $bytes bytes over the $budget-byte budget — $keysClause${skipped > 0 ? ', $skipped key(s) omitted for the budget' : ''}; ask the user or read the app storage for full values)';
  }
  var skipped = 0;
  for (var i = 0; i < entries.length; i++) {
    final line = '  ${entries[i].key}: x';
    final noteOnBreak = noteFor(i == entries.length - 1 ? 0 : entries.length - i);
    if (utf8.encode('$buffer$line\n$noteOnBreak').length > budget) { skipped = entries.length - i; break; }
    buffer.writeln(line);
  }
  buffer.write(noteFor(skipped));
  return buffer.toString();
}
void main() {
  final out = formatAppStateContext(jsonEncode({'big': 'x' * 900}), budget: 250);
  print(out);
}
