+    cut = (cut * 0.9).floor();
+  }
+  return '${text.substring(0, cut)}$note';
+}
+
+/// One-line viewport summary for the agent-bound message (issue #692 C):
+/// logical size, orientation and safe areas of the surface the generated
+/// UI must fit.
